async function main() {
  await mongoose.connect(process.env.MONGODB_URI);
  const db = mongoose.connection.db;

  // Find or create the History subject
  const subjectDoc = await db.collection('subjects').findOne({ name: /^History$/i, schoolId: SCHOOL_ID });

  let SUBJECT_ID;
  if (subjectDoc) {
    SUBJECT_ID = subjectDoc._id;
    console.log('Found History subject:', String(SUBJECT_ID));
  } else {
    const result = await db.collection('subjects').insertOne({
      name: 'History',
      code: 'HIS',
      schoolId: SCHOOL_ID,
      isDeleted: false,
      createdAt: new Date(),
      updatedAt: new Date(),
    });
    SUBJECT_ID = result.insertedId;
    console.log('Created History subject:', String(SUBJECT_ID));
  }

  const now = new Date();
  const baseDoc = {
    schoolId: SCHOOL_ID,
    createdBy: CREATED_BY,
    gradeId: GRADE_ID,
    subjectId: SUBJECT_ID,
    type: 'lesson',
    status: 'approved',
    isDeleted: false,
    createdAt: now,
    updatedAt: now,
    __v: 0,
  };

  const chapters = [
    {
      title: 'Chapter 1: Communism in Russia 1900-1940',
      description: 'Karl Marx, the 1917 revolutions, Lenin consolidates power, the NEP, Marxism-Leninism, the power struggle, and Stalin (collectivisation, industrialisation, purges, women, coming of WWII).',
      order: 1,
      lessons: [
        { title: 'The Roots of Communism and the 1917 Revolutions', description: 'What is communism? Karl Marx, Russia before revolution, February and October 1917 revolutions, Lenin seizes control, Civil War.', blocks: ch1_lesson1, term: 1 },
        { title: 'NEP, Marxism-Leninism, and the Death of Lenin', description: 'The New Economic Policy, how Lenin adapted Marx, the death of Lenin, the power struggle, and how Stalin won.', blocks: ch1_lesson2, term: 1 },
        { title: 'Stalin: Collectivisation, Industrialisation, and Purges', description: 'Collectivisation and dekulakisation, the Holodomor, Five-Year Plans, the Great Purges, women under Stalin, and the coming of WWII.', blocks: ch1_lesson3, term: 1 },
      ],
    },
    {
      title: 'Chapter 2: Capitalism in the USA 1900-1940',
      description: 'The American Dream, the capitalist boom of the 1920s, the Wall Street Crash of 1929, the Great Depression, FDR and the New Deal, and assessment of the New Deal.',
      order: 2,
      lessons: [
        { title: 'The American Dream and the Roaring Twenties', description: 'What is capitalism? The American Dream, reasons for the 1920s boom, cultural changes, who did not share in the boom.', blocks: ch2_lesson1, term: 1 },
        { title: 'Wall Street Crash, Great Depression, and the New Deal', description: 'Causes of the Crash, impact of the Great Depression, FDR and the New Deal, assessment of the New Deal.', blocks: ch2_lesson2, term: 1 },
      ],
    },
    {
      title: 'Chapter 3: Ideas of Race in the Late 19th and 20th Centuries',
      description: 'Notions of race hierarchies, eugenics, the Human Genome Project, and case studies including Nazi Germany and the Holocaust.',
      order: 3,
      lessons: [
        { title: 'Race Hierarchies, Eugenics, and the Human Genome Project', description: '19th-century racial pseudo-science, Social Darwinism, eugenics in practice (USA, Australia, Namibia, SA), and the Human Genome Project.', blocks: ch3_lesson1, term: 2 },
        { title: 'Case Study: Nazi Germany and the Holocaust', description: 'Nazi racial ideology, stages of persecution, the Final Solution, death camps, resistance, and lessons for South Africa.', blocks: ch3_lesson2, term: 2 },
      ],
    },
    {
      title: 'Chapter 4: Nationalisms in the 20th Century',
      description: 'African nationalism (SANNC/ANC, Atlantic Charter, Freedom Charter), Afrikaner nationalism (Broederbond, FAK, economic programme), and case studies on the Middle East and Ghana.',
      order: 4,
      lessons: [
        { title: 'African Nationalism: SANNC/ANC, Atlantic Charter, and the Freedom Charter', description: 'Formation of the SANNC, 1913 Land Act, Atlantic Charter, ANC Youth League, Programme of Action, and the Freedom Charter.', blocks: ch4_lesson1, term: 2 },
        { title: 'Afrikaner Nationalism and Case Studies: Middle East and Ghana', description: 'Broederbond, language movement, FAK, economic programme, Zionism and the Balfour Declaration, Nkrumah and Pan-Africanism.', blocks: ch4_lesson2, term: 2 },
      ],
    },
    {
      title: 'Chapter 5: Apartheid South Africa',
      description: 'Segregation in the 1920s-30s, NP victory of 1948, creation of the apartheid state, apartheid laws, Bantustans, resistance movements, and state repression.',
      order: 5,
      lessons: [
        { title: 'Segregation, the NP Victory, and the Creation of the Apartheid State', description: 'Pre-1948 segregation, the 1948 election, apartheid laws, Verwoerd and Grand Apartheid, the Bantustan system.', blocks: ch5_lesson1, term: 3 },
        { title: 'Resistance to Apartheid', description: 'Labour laws, Coloured franchise fight, Defiance Campaign, Women\'s March, Sharpeville, Rivonia Trial, and state repression.', blocks: ch5_lesson2, term: 3 },
      ],
    },
    {
      title: 'Chapter 6: Revision and Exam Preparation',
      description: 'Exam structure (Paper 1 and Paper 2), source-based question technique, essay writing (PEEL method), content review, and exam tips.',
      order: 6,
      lessons: [
        { title: 'Revision and Exam Preparation', description: 'Paper 1 and Paper 2 structure, source analysis technique, PEEL essay method, key content review, and exam tips.', blocks: ch6_lesson1, term: 4 },
      ],
    },
  ];

  const textbookChapters = [];
  let totalLessons = 0;

  for (const ch of chapters) {
    const resourceIds = [];
    for (const lesson of ch.lessons) {
      const res = await db.collection('contentresources').insertOne({
        ...baseDoc,
        title: lesson.title,
        description: lesson.description,
        blocks: lesson.blocks,
        term: lesson.term,
        curriculumNodeId: null,
      });
      resourceIds.push(res.insertedId);
      totalLessons++;
      console.log('  Inserted: ' + lesson.title + ' (' + lesson.blocks.length + ' blocks)');
    }

    textbookChapters.push({
      id: new mongoose.Types.ObjectId().toString(),
      title: ch.title,
      description: ch.description,
      order: ch.order,
      curriculumNodeId: null,
      resources: resourceIds.map(function (id, i) { return { resourceId: id, order: i }; }),
    });
  }

  // Create textbook
  const textbook = await db.collection('textbooks').insertOne({
    title: 'Grade 11 History \u2014 CAPS Textbook',
    description: 'Complete CAPS-aligned textbook covering Communism in Russia, Capitalism in the USA, Ideas of Race, Nationalisms, Apartheid South Africa, and exam preparation for the Grade 11 History examination.',
    schoolId: SCHOOL_ID,
    gradeId: GRADE_ID,
    subjectId: SUBJECT_ID,
    status: 'published',
    chapters: textbookChapters,
    createdBy: CREATED_BY,
    isDeleted: false,
    createdAt: now,
    updatedAt: now,
    __v: 0,
  });

  console.log('\n========================================');
  console.log('  TEXTBOOK: Grade 11 History');
  console.log('  ID: ' + String(textbook.insertedId));
  console.log('  Chapters: ' + textbookChapters.length);
  console.log('  Lessons: ' + totalLessons);
  console.log('========================================');

  await mongoose.disconnect();
}

main().catch(function (err) { console.error(err); process.exit(1); });
